// --- CLEAN & FILTER SCRAPED X POSTS FOR PAYMENTS / FINTECH INTELLIGENCE ---

const rawItems = $input.all();
const allPosts = [];

// Flatten all results from the Apify dataset response
for (const item of rawItems) {
  const data = item.json;
  if (Array.isArray(data)) {
    allPosts.push(...data);
  } else if (data && typeof data === 'object') {
    allPosts.push(data);
  }
}

// ── Priority signal keywords ──────────────────────────────────────────────
const HIGH_PRIORITY_KEYWORDS = [
  // Central bank / macro
  'CBDC', 'central bank digital currency', 'FedNow', 'Federal Reserve',
  'interest rate', 'rate hike', 'rate cut', 'basis points', 'monetary policy',
  'BIS', 'Bank for International Settlements', 'inflation', 'fed funds',
  // Stablecoin / crypto regulation
  'stablecoin', 'USDC', 'USDT', 'tether', 'crypto regulation', 'SEC crypto',
  'digital asset', 'tokenized', 'blockchain payment', 'crypto bill',
  // Payments infrastructure
  'interchange', 'payment rails', 'real-time payment', 'instant payment',
  'open banking', 'API banking', 'payment network', 'card network',
  'Durbin', 'Regulation E', 'ACH', 'wire transfer', 'SWIFT',
  // Fintech / product moves
  'Visa', 'Mastercard', 'Stripe', 'PayPal', 'Square', 'Block',
  'Apple Pay', 'Google Pay', 'Klarna', 'Affirm', 'BNPL',
  'acquires', 'acquisition', 'merger', 'partnership', 'launches', 'announces',
  'raises', 'funding', 'Series', 'IPO', 'valuation',
  // Regulatory / policy
  'regulation', 'compliance', 'enforcement', 'fine', 'sanction',
  'CFPB', 'OCC', 'FinCEN', 'AML', 'KYC'
];

// ── Trusted payments/fintech accounts ────────────────────────────────────
const TRUSTED_ACCOUNTS = [
  'paymentssource', 'pymnts', 'visanews', 'stripe', 'mastercard',
  'federalreserve', 'bis_org', 'reuters', 'bloomberg', 'ft',
  'wsj', 'cnbc', 'fortunemagazine', 'theinformation'
];

// ── Spam / noise filters ──────────────────────────────────────────────────
const SPAM_PATTERNS = [
  /follow me/i,
  /click here/i,
  /DM for/i,
  /giveaway/i,
  /airdrop/i,
  /moon.*crypto/i,
  /\bRT\b.*\bRT\b/i,
  /get rich/i,
  /100x/i
];

const seen = new Set();
const cleaned = [];

for (const post of allPosts) {
  // Normalize field names across Apify actor versions
  const text = post.text || post.full_text || post.tweet || post.content || '';
  const author = (
    post.author?.userName ||
    post.user?.screen_name ||
    post.username ||
    post.screenName || ''
  ).toLowerCase();
  const createdAt = post.createdAt || post.created_at || post.timestamp || '';
  const likes = post.likeCount || post.favorite_count || post.likes || 0;
  const retweets = post.retweetCount || post.retweet_count || post.retweets || 0;
  const url = post.url || post.tweet_url || (post.id ? `https://x.com/i/web/status/${post.id}` : '');
  const tweetId = post.id || post.tweet_id || url;

  // Skip empty or duplicate posts
  if (!text || !text.trim()) continue;
  if (seen.has(tweetId)) continue;
  seen.add(tweetId);

  // Skip spam
  const isSpam = SPAM_PATTERNS.some(p => p.test(text));
  if (isSpam) continue;

  // Skip very short posts with no substance (after stripping URLs)
  const strippedText = text.replace(/https?:\/\/\S+/g, '').trim();
  if (strippedText.length < 30) continue;

  // Score relevance
  const textLower = text.toLowerCase();
  const matchedKeywords = HIGH_PRIORITY_KEYWORDS.filter(kw =>
    textLower.includes(kw.toLowerCase())
  );
  const isTrustedAccount = TRUSTED_ACCOUNTS.some(acc => author.includes(acc));

  const relevanceScore =
    matchedKeywords.length +
    (isTrustedAccount ? 3 : 0) +
    (likes > 200 ? 2 : likes > 50 ? 1 : 0) +
    (retweets > 100 ? 2 : retweets > 25 ? 1 : 0);

  // Must have at least one keyword match or be from a trusted account
  if (relevanceScore === 0) continue;

  // Clean text
  const cleanText = text
    .replace(/\n{3,}/g, '\n\n')
    .replace(/[ \t]{2,}/g, ' ')
    .trim();

  // Tag signal category for Claude context
  const signalCategory = (() => {
    const tl = textLower;
    if (/cbdc|fednow|federal reserve|bis|interest rate|monetary|rate hike|rate cut/.test(tl)) return 'CENTRAL_BANK';
    if (/stablecoin|usdc|usdt|tether|crypto regulation|digital asset|tokenized|blockchain payment/.test(tl)) return 'CRYPTO_REGULATORY';
    if (/interchange|payment rail|real.time payment|open banking|ach|swift|durbin/.test(tl)) return 'PAYMENT_INFRASTRUCTURE';
    if (/visa|mastercard|stripe|paypal|square|apple pay|google pay|klarna|affirm|bnpl/.test(tl)) return 'FINTECH_PRODUCT';
    if (/regulation|cfpb|occ|fincen|aml|kyc|compliance|fine|sanction/.test(tl)) return 'REGULATORY';
    return 'GENERAL_FINTECH';
  })();

  cleaned.push({
    json: {
      text: cleanText,
      author: author || 'unknown',
      createdAt,
      likes,
      retweets,
      url,
      matchedKeywords,
      relevanceScore,
      isTrustedAccount,
      signalCategory
    }
  });
}

// Sort by relevance score descending, cap at 60 posts for Claude
cleaned.sort((a, b) => b.json.relevanceScore - a.json.relevanceScore);
const top = cleaned.slice(0, 60);

// If no posts passed filtering, signal downstream
if (top.length === 0) {
  return [{
    json: {
      noPosts: true,
      message: 'No relevant payments/fintech posts found in the last 24 hours.',
      posts: []
    }
  }];
}

// Format posts into a readable block for Claude
const formattedPosts = top.map((item, i) => {
  const p = item.json;
  const dateStr = p.createdAt ? new Date(p.createdAt).toUTCString() : 'N/A';
  return [
    `[${i + 1}] @${p.author} | ${dateStr} | Likes: ${p.likes} | RTs: ${p.retweets} | Category: ${p.signalCategory}`,
    p.text,
    `URL: ${p.url}`,
    `Matched: ${p.matchedKeywords.slice(0, 5).join(', ')}`
  ].join('\n');
}).join('\n\n---\n\n');

return [{
  json: {
    noPosts: false,
    postCount: top.length,
    formattedPosts,
    posts: top.map(i => i.json)
  }
}];

