// Extract Claude's text response from the Messages API response
const item = $input.first();
const response = item.json;

let analysisText = '';

if (response && response.content && Array.isArray(response.content)) {
  const textBlock = response.content.find(b => b.type === 'text');
  analysisText = textBlock ? textBlock.text : JSON.stringify(response.content);
} else if (response && response.completion) {
  analysisText = response.completion;
} else {
  analysisText = JSON.stringify(response);
}

// Detect urgency signals
const hasBuySignal = /buy signal/i.test(analysisText);
const hasUrgent = /\[URGENT\]|urgent/i.test(analysisText);
const isMajorSignal = hasBuySignal || hasUrgent;

// Build a clean date string
const today = new Date();
const dateStr = today.toLocaleDateString('en-US', {
  weekday: 'long', year: 'numeric', month: 'long', day: 'numeric'
});

// Truncate for Slack (Slack blocks have a 3000 char limit per section)
const SLACK_MAX = 2900;
const slackBody = analysisText.length > SLACK_MAX
  ? analysisText.slice(0, SLACK_MAX) + '...\n\n_(truncated — see Notion for full report)_'
  : analysisText;

// Determine signal emoji for Slack header
const signalEmoji = hasBuySignal ? ':green_circle:' : hasUrgent ? ':red_circle:' : ':large_yellow_circle:';

return [{
  json: {
    analysisText,
    slackBody,
    hasBuySignal,
    hasUrgent,
    isMajorSignal,
    signalEmoji,
    dateStr,
    model: response.model || 'claude-sonnet-4-6',
    inputTokens: response.usage?.input_tokens || 0,
    outputTokens: response.usage?.output_tokens || 0
  }
}];
